-- objectives get these creatures added (map, minimap, nameplates and tooltips use them)
ns.ATT_OBJECTIVES = ns.ATT_OBJECTIVES or {}
for questID, objs in pairs(ns.SPAWN_PROVIDERS) do
  local q = ns.ATT_OBJECTIVES[questID] or {}
  ns.ATT_OBJECTIVES[questID] = q
  for index, ids in pairs(objs) do
    local o = q[index] or { {}, {}, {} }
    q[index] = o
    o[1] = o[1] or {}
    local have = {}
    for _, id in ipairs(o[1]) do have[id] = true end
    for _, id in ipairs(ids) do if not have[id] then o[1][#o[1] + 1] = id end end
  end
end
